// Follow-up Cron — 3h then 24h for unanswered quotes
// - Looks for leads where next_followup <= now, paused=false, follow_up_count < 2
// - Sends Telegram follow-up if lead.phone starts with "tg:"; otherwise call your WhatsApp sender webhook
//
// No n8n variables ($env) used. Sakhr will fill placeholders.

const SUPABASE_URL = 'https://xfibcjhshpmqkrhlpsoa.supabase.co';
const SUPABASE_KEY = 'eyJ-REDACTED-SERVICE-ROLE';

const SB_HEADERS = {
  apikey: SUPABASE_KEY,
  Authorization: `Bearer ${SUPABASE_KEY}`,
  'Content-Type': 'application/json',
  Prefer: 'return=representation',
};

const now = new Date();

async function sbGet(path) {
  return await this.helpers.httpRequest({
    method: 'GET',
    url: `${SUPABASE_URL}/rest/v1/${path}`,
    headers: SB_HEADERS,
    json: true,
  });
}

async function sbPatch(path, body) {
  return await this.helpers.httpRequest({
    method: 'PATCH',
    url: `${SUPABASE_URL}/rest/v1/${path}`,
    headers: SB_HEADERS,
    body,
    json: true,
  });
}

async function sendTelegram(chatId, text) {
  await this.helpers.httpRequest({
    method: 'POST',
    url: `https://api.telegram.org/botREDACTED_TELEGRAM_BOT_TOKEN/sendMessage`,
    headers: { 'Content-Type': 'application/json' },
    body: { chat_id: chatId, text },
    json: true,
  });
}

async function sendWhatsApp(phone, text) {
  await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://n8n.arcadia-tour.cloud/webhook/laila-v4',
    headers: { 'Content-Type': 'application/json' },
    body: { phone, message: text },
    json: true,
  });
}

const due = await sbGet.call(this,
  `leads?paused=eq.false&follow_up_count=lt.2&next_followup=lte.${now.toISOString()}&stage=eq.quoted&select=phone,name,destination,follow_up_count,telegram_chat_id`
);

if (!Array.isArray(due) || due.length === 0) {
  return [{ json: { status: 'idle', checked_at: now.toISOString() } }];
}

const results = { sent: [], errors: [], checked_at: now.toISOString() };

for (const lead of due) {
  try {
    const count = lead.follow_up_count || 0;

    const msg = count === 0
      ? `هلا ${lead.name || 'بك'} 👋\nبس أتأكد وصلك عرض السعر؟ إذا تبون أعدّل شي (فندق/مدة/عدد) قولي لي 😊`
      : `هلا ${lead.name || 'بك'} 🌟\nآخر تذكير لطيف — الأسعار تتغير حسب التوفر. تبون نثبت الحجز اليوم؟ العربون 20٪ وبعدها الجوازات 😊`;

    if (String(lead.phone).startsWith('tg:')) {
      if (!lead.telegram_chat_id) throw new Error('missing telegram_chat_id');
      await sendTelegram.call(this, lead.telegram_chat_id, msg);
    } else {
      await sendWhatsApp.call(this, lead.phone, msg);
    }

    const newCount = count + 1;
    const nextFU = newCount === 1
      ? new Date(Date.now() + 24 * 60 * 60 * 1000).toISOString()
      : null;

    await sbPatch.call(this, `leads?phone=eq.${encodeURIComponent(lead.phone)}`,
      { follow_up_count: newCount, next_followup: nextFU, stage: newCount >= 2 ? 'followup' : 'quoted' }
    );

    results.sent.push({ phone: lead.phone, follow_up_count: newCount, next_followup: nextFU });
  } catch (e) {
    results.errors.push({ phone: lead.phone, error: e.message });
  }
}

return [{ json: results }];
